/**
 * Aplica un desplaçament aleatori a unes coordenades dins d'un radi en km.
 * Això permet que a partir d'un "seed" de ciutat, puguem caure en qualsevol carrer
 * sense repetir exactament el mateix punt.
 */
export function applyRandomOffset(coords: Coords, radiusKm: number): Coords {
  // Conversió aproximada: 1 grau latitud ~= 111 km
  // 1 grau longitud ~= 111 * cos(lat) km
  const latOffset = (Math.random() * 2 - 1) * (radiusKm / 111);
  const lngOffset = (Math.random() * 2 - 1) * (radiusKm / (111 * Math.cos((coords.lat * Math.PI) / 180)));

  return {
    lat: coords.lat + latOffset,
    lng: coords.lng + lngOffset
  };
}

/**
 * Retorna una ubicació equilibrada:
 * - 5% dels cops (Math.random() < 0.05) força una ciutat del pool URBÀ (Seeds + Radius).
 * - 95% dels cops (resta) fa un RNG pur (Bounding Box) per mantenir el feeling salvatge del joc.
 */
export function getBalancedLocation(mode: string): Coords {
  const forceUrban = Math.random() < 0.05;

  if (forceUrban) {
    let seeds: Coords[];
    if (mode === 'catalunya') {
      seeds = CATALUNYA_URBAN_SEEDS;
    } else {
      seeds = WORLD_URBAN_SEEDS;
    }
    const baseCoords = seeds[Math.floor(Math.random() * seeds.length)];
    return applyRandomOffset(baseCoords, 4); // Radi de 4km per ciutats
  } else {
    // 75% - RNG PUR (THE BOX)
    if (mode === 'catalunya') {
      return randomCatalunyaCoords();
    } else {
      return randomBiasedCoords();
    }
  }
}

// Genera coordenades aleatòries biaixades cap a masses de terra habitades
export function randomBiasedCoords(): Coords {
  const regions = [
    { latMin: 35, latMax: 70, lngMin: -10, lngMax: 40, weight: 18 },   // Europa
    { latMin: 20, latMax: 50, lngMin: 60, lngMax: 145, weight: 22 },   // Àsia Est/SE
    { latMin: -35, latMax: 37, lngMin: -20, lngMax: 55, weight: 12 },  // Àfrica
    { latMin: 25, latMax: 70, lngMin: -140, lngMax: -55, weight: 18 }, // Nord-amèrica
    { latMin: -55, latMax: 15, lngMin: -82, lngMax: -35, weight: 10 }, // Sud-amèrica
    { latMin: -45, latMax: -10, lngMin: 112, lngMax: 155, weight: 8 }, // Austràlia
    { latMin: -5, latMax: 25, lngMin: 95, lngMax: 145, weight: 8 },    // Illes SE Àsia
    { latMin: 30, latMax: 45, lngMin: 25, lngMax: 65, weight: 4 },     // Orient Mitjà
  ];

  const totalWeight = regions.reduce((s, r) => s + r.weight, 0);
  let rand = Math.random() * totalWeight;

  for (const r of regions) {
    rand -= r.weight;
    if (rand <= 0) {
      return {
        lat: r.latMin + Math.random() * (r.latMax - r.latMin),
        lng: r.lngMin + Math.random() * (r.lngMax - r.lngMin),
      };
    }
  }
  return { lat: Math.random() * 140 - 55, lng: Math.random() * 360 - 180 };
}

// Genera coordenades aleatòries dins d'una caixa delimitadora (Bounding Box) per a Catalunya
export function randomCatalunyaCoords(): Coords {
  // Límits geogràfics aproximats de Catalunya
  const minLat = 40.52; // Sud (Montsià)
  const maxLat = 42.86; // Nord (Val d'Aran)
  const minLng = 0.15;  // Oest (Terra Alta)
  const maxLng = 3.33;  // Est (Cap de Creus)

  const lat = minLat + Math.random() * (maxLat - minLat);
  const lng = minLng + Math.random() * (maxLng - minLng);

  return { lat, lng };
}

// Genera coordenades aleatòries dins d'una caixa delimitadora per a Barcelona (Pixapins)
// Aplica restricció diagonal per excloure la costa (Mar Mediterrani) del bounding box.
// La línia de costa de Barcelona segueix aproximadament: lat = 41.46 - 0.55 * (lng - 2.10)
// Qualsevol punt per sota d'aquesta línia (al mar) és rebutjat i es regenera.
export function randomPixapinsCoords(): Coords {
  // Límits geogràfics aproximats de Barcelona ciutat i àrea molt propera
  const minLat = 41.34;
  const maxLat = 41.45;
  const minLng = 2.10;
  const maxLng = 2.22;

  let lat: number;
  let lng: number;
  let isInland: boolean;

  do {
    lat = minLat + Math.random() * (maxLat - minLat);
    lng = minLng + Math.random() * (maxLng - minLng);
    // Restricció lineal de la costa: la línia de costa de Barcelona va de SW a NE (pendent positiu)
    // Formula: lat > 41.35 + 0.85 * (lng - 2.15) assegura que el punt és terra endins
    const coastlineThreshold = 41.35 + 0.85 * (lng - 2.15);
    isInland = lat > coastlineThreshold;
  } while (!isInland);

  return { lat, lng };
}

