export function calculateYearScore(guessYear: number, actualYear: number): number {
  const diff = Math.abs(guessYear - actualYear);
  if (diff === 0) return 2500;
  const score = Math.round(2500 * Math.exp(-diff / 300));
  return Math.max(0, score);
}
